import{_ as t,I as n,c as o,o as i,j as a,J as s,a5 as d,a as l}from"./chunks/framework.CUJoMJm2.js";const b=JSON.parse('{"title":"ADR 004: Binary FrameId Representation","description":"","frontmatter":{},"headers":[],"relativePath":"adr/004-binary-frameid.md","filePath":"adr/004-binary-frameid.md","lastUpdated":1768070912000}'),c={name:"adr/004-binary-frameid.md"};function p(m,e,g,u,y,f){const r=n("CopyOrDownloadAsMarkdownButtons");return i(),o("div",null,[e[0]||(e[0]=a("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /adr/004-binary-frameid.md for this page in Markdown format",-1)),e[1]||(e[1]=a("h1",{id:"adr-004-binary-frameid-representation",tabindex:"-1"},[l("ADR 004: Binary FrameId Representation "),a("a",{class:"header-anchor",href:"#adr-004-binary-frameid-representation","aria-label":"Permalink to “ADR 004: Binary FrameId Representation”"},"​")],-1)),s(r),e[2]||(e[2]=d('<ul><li><strong>Date</strong>: 2025-11-23</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: SBP</li><li><strong>Tags</strong>: protocol, breaking-change, wire-format</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Initial wire format treated <code>FrameId</code> as UTF-8 text with space-padding to 16 bytes. This created:</p><ul><li><strong>Semantic confusion</strong>: Random bytes as text with padding/trimming logic</li><li><strong>Interop fragility</strong>: UTF-8 handling differs across runtimes</li><li><strong>Entropy underutilization</strong>: Original spec used 12 bytes, encoded as 16-char hex</li><li><strong>Developer friction</strong>: Forced string ops on opaque data; humans need hex anyway</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>FrameId</code> is 16 opaque bytes (128 bits) generated via <code>crypto.getRandomValues()</code>.</p><p><strong>Wire:</strong> 16 raw bytes, no encoding or padding, no semantic bits or structure.</p><p><strong>Type:</strong> <code>FrameId = Uint8Array &amp; { __brand: &quot;FrameId&quot; }</code></p><p><strong>Validation:</strong> <code>asFrameId()</code> enforces exactly 16 bytes. No bit-level validation; FrameId is treated as pure entropy.</p><p><strong>Key distinction:</strong> Frame header flags (byte 1) are separate from FrameId. FrameId has no semantic bits or structure.</p><p><strong>Human representation:</strong> Helpers for logs/JSON:</p><ul><li><code>frameIdToHex(id) → string</code> (32-char lowercase hex)</li><li><code>frameIdFromHex(hex) → FrameId</code> (validates format)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Breaking wire change</strong>: Pre-1.0, acceptable.</li><li><strong>Simpler codec</strong>: No padding/trimming logic; just read/write 16 bytes.</li><li><strong>Collision safety</strong>: 128-bit entropy is astronomically safe.</li><li><strong>Clarity</strong>: No accidental string operations on random data.</li><li><strong>Consistency</strong>: All runtimes read the same 16 bytes.</li></ul>',14))])}const _=t(c,[["render",p]]);export{b as __pageData,_ as default};
